import 'package:flutter/material.dart';\r\nimport 'package:provider/provider.dart';\r\n\r\nimport '../providers/auth_provider.dart';\r\nimport '../screens/auth/splash_screen.dart';\r\nimport '../screens/auth/login_screen.dart';\r\nimport '../screens/customer/customer_main_scaffold.dart';\r\nimport '../screens/staff/staff_main_scaffold.dart';\r\nimport '../screens/admin/admin_main_scaffold.dart';\r\n\r\n/// Core Routing Logic\r\n/// This widget listens to [AuthProvider] and routes to the correct application\r\n/// flow based on the user's role, strictly adhering to the PRD.\r\nclass AuthWrapper extends StatelessWidget {\r\n  const AuthWrapper({super.key});\r\n\r\n  @override\r\n  Widget build(BuildContext context) {\r\n    final authProvider = context.watch<AuthProvider>();\r\n\r\n    // Handle Loading State\r\n    if (authProvider.isLoading) {\r\n      return const SplashScreen();\r\n    }\r\n\r\n    // Handle Empty/Unauthenticated State\r\n    if (!authProvider.isAuthenticated) {\r\n      return const LoginScreen();\r\n    }\r\n\r\n    // Handle Success/Authenticated State - Route by Role\r\n    final role = authProvider.userRole;\r\n    \r\n    switch (role) {\r\n      case 'customer':\r\n        return const CustomerMainScaffold();\r\n      case 'staff':\r\n        return const StaffMainScaffold();\r\n      case 'admin':\r\n        return const AdminMainScaffold();\r\n      default:\r\n        // Handle Error State for unrecognized roles\r\n        return const Scaffold(\r\n          body: Center(\r\n            child: Text('Error: Unrecognized user role.'),\r\n          ),\r\n        );\r\n    }\r\n  }\r\n}\r\n
